M(ptf, r"""
public static String costShort(java.util.UUID u, @PKG@.PetInv inv, String egg) {
  int ci = @PKG@.PetHatchery.craftIndex(egg);
  if (ci < 0) return "";
  String[] ids = @PKG@.PetHatchery.inIds(ci);
  int[] q = @PKG@.PetHatchery.inQty(ci);
  StringBuilder b = new StringBuilder();
  for (int i = 0; i < ids.length; i++) {
    if (ids[i].startsWith("@EGGP@")) continue;           // an upgrade's egg one rarity below = the selected egg (SkyyMenu's box names it)
    long h = (inv == null ? 0L : (long) inv.count(ids[i])) + @PKG@.PetHatchery.voidHave(u, ids[i]);
    if (h > (long) q[i]) h = (long) q[i];
    if (b.length() > 0) b.append(" + ");
    b.append(@PKG@.PetHatchery.inName(ids[i])).append(' ').append(h).append('/').append(q[i]);
  }
  return b.toString();
}""".replace("@EGGP@", EGG.PREFIX))
