# the two-press ops (fuse / reb / take): the first press stores its key + the time and asks; the second with the same key within CONF_MS does it
# (fix, critic tab2-crit-safety 1: an old ask never confirms - it expires after 15 s, and the screen's first read clears it (apply mode 0, arg 7 = 1))
M(ptf, r"""
public static boolean confirmed(java.util.UUID u, String c) {
  Object o = CONF.remove(u);
  if (!(o instanceof String)) return false;
  String s = (String) o;
  int i = s.lastIndexOf((char) 30);
  if (i < 0 || !s.substring(0, i).equals(c)) return false;
  long at = -1L;
  try { at = Long.parseLong(s.substring(i + 1)); } catch (Throwable t) { at = -1L; }
  long age = System.currentTimeMillis() - at;
  return at > 0L && age >= 0L && age <= CONF_MS;
}""")
M(ptf, r"""
public static String ask(java.util.UUID u, String c, String m) {
  if (m != null && m.startsWith("=")) CONF.put(u, c + String.valueOf((char) 30) + System.currentTimeMillis()); else CONF.remove(u);
  return m;
}""")
M(ptf, r"""
public static int num(String s, int d) {
  try { return Integer.parseInt(s.trim()); } catch (Throwable t) { return d; }
}""")
M(ptf, r"""
public static String act(java.util.UUID u, String tok, String op, String arg, String by, @PKG@.PetInv inv, @PR@ pr, @REF@ ref, @ST@ st) {
  if (u == null || op == null) return "-That did not work - nothing changed.";
  ACTS.incrementAndGet();
  if (!@PKG@.PetsCfg.ON) return "-Pets are switched off on this server.";
  if (@PKG@.PetStore.DIR == null) return "-Pets are not ready yet - try again in a moment.";
  if (@PKG@.PetOps.busy(u)) return "=Your profile is switching - try again in a moment.";
  String key = @PKG@.PetStore.pkey(u);
  if (tok == null || !tok.equals(key)) { STALE.incrementAndGet(); CONF.remove(u); return "=Your profile changed - here are its pets. Nothing changed."; }
  String a = arg == null ? "" : arg;
  long now = System.currentTimeMillis();
  String g = op + "|" + a;
  Object lo = LAST.get(u);
  if (lo instanceof String) {
    String ls = (String) lo;
    int c = ls.lastIndexOf((char) 30);
    long at = 0L;
    try { at = c < 0 ? 0L : Long.parseLong(ls.substring(c + 1)); } catch (Throwable t) { at = 0L; }
    if (c >= 0 && ls.substring(0, c).equals(g) && now - at >= 0L && now - at < GUARD_MS) { GUARD.incrementAndGet(); return "=One moment."; }
  }
  LAST.put(u, g + String.valueOf((char) 30) + now);
  if (!"fuse".equals(op) && !"reb".equals(op) && !"take".equals(op)) CONF.remove(u);
  @PKG@.PetRec r = @PKG@.PetStore.get(key);
  if (r == null || r.bad) return "-Your pet file could not be read - an admin has been told. Nothing was changed.";
  String who = by == null ? "bridge" : by;
  if ("slot".equals(op)) {
    int b = a.lastIndexOf('|');
    String id = b < 0 ? a : a.substring(0, b);
    int n = b < 0 ? 1 : num(a.substring(b + 1), 0);
    if (n != 1 && n != 2) return "-There is no such slot.";
    if (!r.has(id)) return "-That pet is not yours any more.";
    if (r.slotOf(id) == n) return "=That pet is already in your " + @PKG@.PetOps.slotName(n) + ".";
    return @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.toSlot(u, id, n, who), true);
  }
  if ("out".equals(op)) {
    int n = num(a, 0);
    if (n != 1 && n != 2) return "-There is no such slot.";
    String id = r.active(n);
    if (id == null || id.length() == 0) return "-That slot is empty.";
    return @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.takeOut(u, id, who), false);
  }
  if ("ride".equals(op)) return @PKG@.PetRideFn.ride(u, @PKG@.PetRide.now());
  long cm = -1L;
  try { cm = @PKG@.PetOps.combatMs(st, ref); } catch (Throwable t) { cm = -1L; }
  if ("fuse".equals(op)) {
    if (!r.has(a)) { CONF.remove(u); return "-That pet is not yours any more."; }
    if (@PKG@.PetDragon.isDragon(r.kindOf(a))) { CONF.remove(u); return "-Dragons cannot be fused (one dragon per profile)."; }
    int rr = r.rarityOf(a);
    String fk = @PKG@.PetOps.fodderKey(r, a);
    String c = "fuse|" + a + "|" + rr + "|" + fk;
    if (confirmed(u, c)) return @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.fuse(u, a, rr, fk, who, cm), true);
    return ask(u, c, @PKG@.PetOps.fuseAsk(u, a, cm));
  }
  if ("reb".equals(op)) {
    if (!r.has(a)) { CONF.remove(u); return "-That pet is not yours any more."; }
    int rb = r.rebirthOf(a);
    String c = "reb|" + a + "|" + rb;
    if (confirmed(u, c)) return @PKG@.PetSnd.slotDone(u, @PKG@.PetOps.rebirth(u, a, rb, who, cm), true);
    return ask(u, c, @PKG@.PetOps.rebAsk(u, a, cm));
  }
  if ("craft".equals(op)) {
    if (@PKG@.PetHatchery.craftIndex(a) < 0) return "-That egg cannot be crafted here.";
    if (inv == null) return "-Your inventory could not be read - nothing moved.";
    return @PKG@.PetHatchery.craft(u, inv, a, who);
  }
  if ("place".equals(op)) {
    if (inv == null) return "-Your inventory could not be read - nothing moved.";
    Object[] res = @PKG@.PetHatchery.place(u, inv, a, who);
    String m = (String) res[0];
    if (m.startsWith("+") && inv instanceof @PKG@.PetInvReal && "inv".equals(res[2])) { try { @PKG@.PetEggSave.force(((@PKG@.PetInvReal) inv).p, ref, st, (String) res[1]); } catch (Throwable t) { } }
    return m;
  }
  if ("hatch".equals(op) || "take".equals(op)) {
    int b = a.indexOf('|');
    int n = num(b < 0 ? a : a.substring(0, b), -1);
    String hid = b < 0 ? "" : a.substring(b + 1);
    String[] ln = @PKG@.PetHatchery.line(r, n);
    if (ln == null) { CONF.remove(u); return "-That slot is empty."; }
    if (!ln[2].equals(hid)) { CONF.remove(u); return "=That slot changed - here it is again."; }
    if ("take".equals(op)) {
      if (@PKG@.PetHatchery.ready(ln, @PKG@.PetHatchery.now(), u)) { CONF.remove(u); return "=It is ready now - press Hatch."; }   // fix (critic tab2-crit-safety 2)
      String c = "take|" + n + "|" + hid;
      if (confirmed(u, c)) {
        if (inv == null) return "-Your inventory could not be read - nothing moved.";
        Object[] res = @PKG@.PetHatchery.takeOut(u, inv, n, hid, who);
        String m = (String) res[0];
        if (m.startsWith("+") && inv instanceof @PKG@.PetInvReal) { try { @PKG@.PetEggSave.force(((@PKG@.PetInvReal) inv).p, ref, st, (String) res[1]); } catch (Throwable t) { } }
        return m;
      }
      return ask(u, c, "=Take the " + @PKG@.PetEggDefs.nameOf(ln[0]) + " out of slot " + n + "? Its hatch timer is lost (" + @PKG@.PetHatchery.dur(@PKG@.PetHatchery.left(ln, @PKG@.PetHatchery.now(), u)) + " left). Press Take out again.");
    }
    if (!@PKG@.PetHatchery.ready(ln, @PKG@.PetHatchery.now(), u)) return "-Still hatching - " + @PKG@.PetHatchery.dur(@PKG@.PetHatchery.left(ln, @PKG@.PetHatchery.now(), u)) + " left.";
    Object[] res = @PKG@.PetHatchery.hatch(u, n, hid, who);
    String m = (String) res[0];
    if (!m.startsWith("+")) return m;
    boolean ok = false;
    java.util.function.Function opn = @PKG@.PetHatchery.OPENER;
    try { if (opn != null && pr != null && ref != null && st != null) ok = Boolean.TRUE.equals(opn.apply(new Object[] { pr, ref, st, ln[0], res })); }
    catch (Throwable t) { @PKG@.PetsLog.warnOnce("tabhatch:" + t.getClass().getName(), "the hatch reel page could not open (the result is told in chat): " + t); }
    if (ok) return "^" + m.substring(1);
    @PKG@.PetEgg.ANIM.remove((String) res[1]);
    @PKG@.PetEgg.reveal(u, @PKG@.PetStore.get(key), (String) res[1]);
    return m;
  }
  return "-Unknown pet action.";
}""")
M(ptf, r"""
public static Object[] ctx(java.util.UUID u) {
  try {
    @PR@ pr = @UNI@.get().getPlayer(u);
    if (pr == null) return null;
    @REF@ ref = pr.getReference();
    if (ref == null || !ref.isValid()) return null;
    @ST@ st = ref.getStore();
    if (st == null || !st.isInThread()) return null;
    return new Object[] { pr, ref, st, @PKG@.PetInvReal.of(st, ref) };
  } catch (Throwable t) { return null; }
}""")
M(ptf, r"""
public static Object[] ctxOrTest(java.util.UUID u) {
  Object[] c = ctx(u);
  if (c != null) return c;
  java.util.function.Function ti = TEST_INV;
  if (ti == null) return null;
  Object iv = ti.apply(u);
  return new Object[] { null, null, null, iv instanceof @PKG@.PetInv ? iv : null };
}""")
M(ptf, r"""
public static int ia(Object[] a, int i, int d) { return a.length > i && a[i] instanceof Number ? ((Number) a[i]).intValue() : d; }""")
M(ptf, r"""
public static String sa(Object[] a, int i) { return a.length > i && a[i] instanceof String ? (String) a[i] : ""; }""")
M(ptf, r"""
public Object apply(Object o) {
  try {
    Object[] a = o instanceof Object[] ? (Object[]) o : new Object[] { o };
    if (a.length == 0 || !(a[0] instanceof java.util.UUID)) return null;
    java.util.UUID u = (java.util.UUID) a[0];
    Object[] c = ctxOrTest(u);
    if (c == null) return null;
    @PKG@.PetInv inv = (@PKG@.PetInv) c[3];
    if (this.mode == 0 && ia(a, 7, 0) == 1) CONF.remove(u);          // the screen's first read: no ask from an earlier visit survives
    if (this.mode == 0) return read(u, sa(a, 1), ia(a, 2, 0), ia(a, 3, 0), ia(a, 4, 0), ia(a, 5, 42), sa(a, 6), inv);
    if (a.length < 4 || !(a[1] instanceof String) || !(a[2] instanceof String)) return null;
    @PR@ pr = (@PR@) c[0];
    String by = pr == null ? "bridge" : pr.getUsername();
    return act(u, (String) a[1], (String) a[2], sa(a, 3), by, inv, pr, (@REF@) c[1], (@ST@) c[2]);
  } catch (Throwable t) {
    @PKG@.PetsLog.warnOnce("tabfn" + this.mode + ":" + t.getClass().getName(), "pets:fn:tab" + (this.mode == 1 ? "act" : "") + " failed (logged once): " + t);
    return this.mode == 1 ? "-Something went wrong - nothing changed. The server log has the details." : null;
  }
}""")

